using System;
using System.Diagnostics;
using System.IO;

// PROGRAM: Mengamati Dampak Buffered I/O vs Frekuensi Syscall Trap
const int Iterations = 50_000;

// Uji 1: Simulasi Unbuffered (Setiap byte memicu context switch/write terpisah)
var sw1 = Stopwatch.StartNew();
using (var stream1 = new MemoryStream())
{
    byte b = (byte)'A';
    for (int i = 0; i < Iterations; i++)
    {
        stream1.WriteByte(b); // Banyak overhead pemanggilan write terpisah
    }
}
sw1.Stop();
Console.WriteLine($"Unbuffered I/O (Banyak Write Call Trap): {sw1.ElapsedMilliseconds} ms");

// Uji 2: Buffered I/O (Buffer batch meminimalkan pemanggilan saluran I/O)
var sw2 = Stopwatch.StartNew();
using (var stream2 = new MemoryStream())
using (var buffered = new BufferedStream(stream2, 4096))
{
    byte[] buffer = new byte[Iterations];
    Array.Fill(buffer, (byte)'A');
    buffered.Write(buffer, 0, buffer.Length); // Hanya 1 pemanggilan batch besar!
    buffered.Flush();
}
sw2.Stop();
Console.WriteLine($"Buffered I/O (Write Call Minimal): {sw2.ElapsedMilliseconds} ms");
Console.WriteLine($"Efisiensi: Pemanggilan dalam buffer menghemat overhead context switch!");

