using System;

public class IoOptimizer
{
    public static int CalculateSyscallCount(int messageCount, int messageSizeBytes, int bufferCapacityBytes)
    {
        if (messageCount <= 0 || messageSizeBytes <= 0 || bufferCapacityBytes <= 0) return 0;
        long totalBytes = (long)messageCount * messageSizeBytes;
        long fullFlushes = totalBytes / bufferCapacityBytes;
        long remainder = totalBytes % bufferCapacityBytes;

        long totalSyscalls = fullFlushes + (remainder > 0 ? 1 : 0);
        return (int)totalSyscalls;
    }

    public static void Main()
    {
        Console.WriteLine($"Syscalls: {CalculateSyscallCount(100, 50, 2048)}");
    }
}
